// Spanish (Costa Rica) legal pages, help and dates. Written with "usted",
// as Costa Rican legal text usually is (the Help answers use "vos" like the
// rest of the app). Generated alongside the backend copy — keep them in sync.

const LEGAL_EFFECTIVE_DATE = '15 de noviembre de 2026';
const TERMS_EFFECTIVE_DATE = '13 de noviembre de 2026';

const TERMS_SECTIONS = [
  { h: "En resumen", p: ["Foursome ayuda a golfistas a publicar tee times abiertos y encontrar grupos para jugar. Sea honesto en su perfil, respetuoso con los demás golfistas y use el buen juicio al conocer gente en persona, como lo haría con cualquier aplicación que lo conecta con desconocidos. El resto de esta página explica los detalles."] },
  { h: "Quién puede usar Foursome", p: ["Debe tener al menos 18 años para crear una cuenta de Foursome o usar la aplicación. Al usar Foursome, usted confirma que cumple este requisito y que la información de su perfil es correcta."] },
  { h: "Su cuenta", p: ["Puede usar Foursome como invitado (un perfil guardado solo en su dispositivo, sin correo ni contraseña) o con una cuenta completa (correo y contraseña, administrados por nuestro proveedor de autenticación, Supabase). En ambos casos, usted es responsable de la actividad de su cuenta y de mantener privados sus datos de acceso. Si inicia sesión en un dispositivo que comparte con otras personas, recuerde cerrar sesión al terminar."] },
  { h: "Qué es Foursome, y qué no es", p: ["Foursome es un lugar para que los golfistas publiquen rondas que ya reservaron e inviten a otros a unirse, o para ver rondas que otros golfistas han publicado. No somos un servicio de reservas: publicar o unirse a una ronda en Foursome no reserva un tee time en ningún campo de golf. La pestaña \"Campos\" le permite buscar campos de golf; no reserva nada en su nombre.", "Foursome no está afiliado, respaldado ni operado en conjunto con ningún campo de golf, club o plataforma de reservas. Los nombres y ubicaciones de los campos que muestra la aplicación provienen de OpenStreetMap, un mapa público hecho por la comunidad, no de los campos mismos."] },
  { h: "Publicar y unirse a rondas", p: ["Cuando publica una ronda, los detalles que ingresa (campo, fecha, hora, número de espacios, rango de hándicap, ritmo y notas) son visibles para otros usuarios de Foursome. Cuando alguien pide unirse a su ronda, usted decide si lo aprueba o lo rechaza; Foursome no garantiza que una solicitud sea aprobada ni que una ronda publicada se llene. Usted es responsable de la exactitud de lo que publica, incluido tener de verdad un tee time para compartir."] },
  { h: "Conocer gente en persona", p: ["Foursome lo conecta con otros golfistas, pero la ronda ocurre fuera de nuestra plataforma, en persona. No hacemos verificaciones de antecedentes y no podemos garantizar la identidad, el comportamiento ni el nivel de juego de nadie que conozca por medio de la aplicación. Use el mismo criterio que con cualquier aplicación que lo conecta con desconocidos: considere encontrarse la primera vez en el propio campo, cuéntele a alguien sus planes y confíe en su instinto. Si algo no le parece bien, puede retirarse, bloquear a la otra persona y reportarla."] },
  { h: "Mensajes y conducta", p: ["El chat de una ronda solo lo ven el anfitrión y los participantes aprobados. Al usar Foursome (en el chat, en su bio, en las notas de una ronda o en cualquier otro lugar), no:"], list: ["Acose, amenace ni discrimine a nadie", "Publique spam, estafas ni publicidad no relacionada", "Se haga pasar por otra persona ni falsee su hándicap o identidad", "Comparta información personal de otras personas sin su consentimiento", "Use Foursome para algo ilegal"] },
  { h: "Calificaciones", p: ["Después de una ronda, los participantes pueden calificarse entre sí. Las calificaciones deben reflejar su experiencia honesta y de buena fe jugando con esa persona, no servir para resolver un conflicto ajeno ni para tomar represalias. No califique ni comente sobre alguien con quien no jugó una ronda."] },
  { h: "Bloquear y reportar", p: ["Si prefiere no interactuar con alguien, puede bloquearlo: así se ocultan mutuamente sus rondas y se impiden las solicitudes entre ustedes, en ambas direcciones, y deja de ver sus mensajes en el chat. Si cree que alguien violó estos términos o lo hizo sentir inseguro, puede reportarlo, aparte de bloquearlo, y también puede reportar un mensaje específico del chat. Revisamos los reportes y podemos tomar medidas, como advertir, suspender o eliminar una cuenta, a nuestro criterio."] },
  { h: "Su contenido", p: ["Lo que usted publica le pertenece: su bio, notas de rondas, mensajes y calificaciones. Al publicarlo en Foursome, nos autoriza a guardarlo y mostrarlo a los usuarios a quienes va dirigido (por ejemplo, mostrar las notas de su ronda a quienes buscan en Descubrir, o su bio a quien vea su perfil). Usted es responsable de lo que publica y confirma que tiene derecho a compartirlo."] },
  { h: "Cierre de la cuenta", p: ["Puede eliminar su cuenta en cualquier momento desde Ajustes. Esto elimina de forma permanente su perfil, las rondas que organizó (con su historial de chat), sus calificaciones y, si inició sesión, su cuenta de acceso. Podemos suspender o cerrar su cuenta si viola estos términos."] },
  { h: "Eventos pagados", p: ["Foursome organiza algunos eventos de golf a los que usted se une pagando. Los eventos son presenciales, en el campo de golf indicado en el evento; usted paga por su espacio en ese evento, no por nada dentro de la aplicación.", "Los precios de los eventos están en colones costarricenses. Los pagos los procesa ONVO Pay, con tarjeta o SINPE Móvil, en la página de pago segura de ONVO. Mientras paga, su espacio queda reservado por 20 minutos; se confirma solo cuando ONVO confirma el pago.", "Puede cancelar su espacio con reembolso completo hasta el plazo de cancelación indicado en el evento. Después de ese plazo, los pagos no son reembolsables. Si Foursome cancela un evento, a todas las personas que pagaron se les reembolsa el monto completo (los pagos con tarjeta automáticamente; los pagos por SINPE Móvil a mano en un plazo de 3 días hábiles, ver la Política de reembolsos). Vea la Política de Reembolsos para más detalles.", "Debe tener 18 años o más y una cuenta para pagar un evento. En el evento aplican las reglas propias del campo de golf, y las reglas de conducta de estos términos también aplican a los eventos."] },
  { h: "Sin garantías y limitación de responsabilidad", p: ["Foursome se ofrece \"tal cual\". Trabajamos para que funcione de forma confiable, pero no garantizamos que siempre esté disponible o libre de errores, ni que una ronda, campo o golfista en particular cumpla sus expectativas. En la máxima medida que permita la ley, Foursome no es responsable de disputas, lesiones o pérdidas que surjan de interacciones entre usuarios, ni de las políticas, condiciones o disponibilidad de un campo de golf."] },
  { h: "Cambios a estos términos", p: ["Podemos actualizar estos términos conforme Foursome cambie. Si hacemos un cambio importante, haremos lo posible por avisarle en la aplicación. Seguir usando Foursome después de una actualización significa que acepta los términos revisados."] },
  { h: "Contacto", p: ["¿Preguntas sobre estos términos? Escríbanos a foursomeapp.golf@gmail.com."] },
];

const PRIVACY_SECTIONS = [
  { h: "En resumen", p: ["Recopilamos lo necesario para que Foursome funcione: la información de su perfil, las rondas, mensajes y calificaciones que crea y, solo cuando decide compartirla, su ubicación, para ayudarle a encontrar rondas y campos de golf cercanos. No vendemos sus datos ni los compartimos con anunciantes."] },
  { h: "Información que recopilamos", p: ["Datos de la cuenta: si se registra con correo y contraseña, eso lo maneja nuestro proveedor de autenticación, Supabase; nunca vemos ni guardamos su contraseña. Si inicia sesión con Apple o Google, recibimos de ellos su nombre y su correo (con Apple puede ocultar su correo, y entonces recibimos una dirección de reenvío privada que le llega a usted); nunca vemos su contraseña de Apple o Google. Si usa Foursome como invitado, le asignamos un identificador aleatorio guardado solo en su dispositivo, sin correo ni contraseña.", "Datos del perfil: su nombre, campo de golf habitual, hándicap, bio y foto de perfil (si las agrega), definidos al crear o editar su perfil y visibles para otros usuarios de Foursome. Las fotos se achican en su teléfono antes de subirlas y se guardan con nuestro proveedor de base de datos, Supabase; cualquiera con el enlace de una foto puede verla. Quitar su foto o eliminar su cuenta borra el archivo.", "Rondas, mensajes, calificaciones y reportes: los tee times que publica o a los que pide unirse, los mensajes del chat de una ronda, los grupos que crea o a los que se une (y los mensajes del chat del grupo), las calificaciones y comentarios que deja a otros jugadores, su respuesta después de una ronda sobre si llegaron todos (con la que mostramos las rondas jugadas y el porcentaje de asistencia de cada jugador), y los reportes que hace sobre otra persona o un mensaje. Amigos: las personas que agrega como amigos y las solicitudes de amistad. Eventos: si paga por un grupo, los nombres de sus invitados; si se une a una lista de espera o usa un código de descuento, también eso.", "Ubicación: una vez que la autoriza, la aplicación revisa su ubicación cada vez que la abre o la vuelve a poner en primer plano. Solo lo hace mientras usa la aplicación, nunca en segundo plano. Sus coordenadas se usan para ordenar las rondas por distancia y encontrar campos de golf cercanos (se envían a nuestro servidor en cada búsqueda para consultarlas en OpenStreetMap). No guardamos sus coordenadas.", "En su dispositivo: la aplicación guarda su sesión y sus ajustes en su dispositivo para que no tenga que iniciar sesión cada vez.", "Eventos pagados: si se une a un evento pagado, guardamos su nombre, el evento, el monto, cuándo pagó, cualquier reembolso y las referencias de pago que nos da ONVO. Los datos de su tarjeta y de SINPE Móvil se ingresan en la página de ONVO y van a ONVO, nunca a nosotros. Si usa \"Pedir un evento\", guardamos el campo y la nota que envía.", "Datos de notificaciones: si activa las notificaciones, guardamos una suscripción (un identificador anónimo de su navegador en el sitio web, o un token de Expo en la aplicación) y el idioma de su teléfono, para avisarle de solicitudes, aprobaciones y mensajes en su idioma. Si los deja activados, también le avisamos de rondas nuevas en su campo habitual y de eventos nuevos a menos de 100 km de él (según su campo habitual, nunca su ubicación), y le recordamos la noche anterior una ronda o evento en el que participa. Puede desactivar por separado los avisos de rondas y de eventos en Ajustes."] },
  { h: "Cómo usamos su información", p: ["No usamos su información para publicidad ni la vendemos a terceros."], list: ["Para que funcionen las funciones principales: publicar y unirse a rondas, conectarlo con otros golfistas, el chat de cada ronda, y mostrar calificaciones e historial de rondas en común en los perfiles", "Para ayudarle a encontrar rondas y campos cercanos cuando decide compartir su ubicación", "Para atender reportes y hacer cumplir nuestros Términos del Servicio", "Para enviarle las notificaciones que activó", "Para mantener Foursome seguro y funcionando bien"] },
  { h: "Quién puede ver qué", p: ["Su nombre, campo de golf habitual, hándicap, bio y calificación son visibles para otros usuarios de Foursome, en especial para quien vea una ronda que usted organiza o a la que se une. El chat de una ronda solo lo ven el anfitrión y los participantes aprobados. El chat, la lista de miembros y las rondas solo para miembros de un grupo solo los ven sus miembros; su nombre, campo, descripción, creador y cantidad de miembros los ven todos los usuarios de Foursome. Los reportes que usted hace solo los vemos nosotros. Si paga un evento, los usuarios de Foursome con sesión iniciada pueden ver su nombre en la lista “Quiénes van” de ese evento; los invitados solo ven cuántas personas van. Si comparte una ronda o un evento, cualquiera con el enlace puede ver el campo, la fecha, la hora, los espacios libres y, en los eventos, el precio. Su lista de amigos y las solicitudes de amistad solo las ven usted y la otra persona. Los nombres de los invitados por los que paga solo los vemos usted y nosotros. Las rondas abiertas a todos en un campo aliado de Foursome (fecha, hora y espacios libres, nunca su nombre) y los eventos de ese campo aparecen en la página web pública del campo. Después de un evento podemos publicar resultados y fotos en su página, en las que pueden aparecer quienes asistieron; escríbanos y quitamos una foto suya."] },
  { h: "Terceros con los que trabajamos", p: ["Usamos unos pocos servicios externos para operar Foursome:"], list: ["Supabase: nuestro proveedor de base de datos, autenticación y alojamiento. Su cuenta, perfil y datos de la aplicación se guardan en la infraestructura de Supabase.", "OpenStreetMap (Nominatim y Overpass): datos de mapas públicos hechos por la comunidad, que consultamos para buscar nombres y ubicaciones de campos de golf. Solo enviamos un término de búsqueda o coordenadas, nunca su identidad.", "ONVO Pay: procesa los pagos de eventos pagados (tarjetas y SINPE Móvil). Los datos de pago van directamente a ONVO; la política de privacidad de ONVO explica cómo los maneja."] },
  { h: "Cuánto tiempo guardamos sus datos", p: ["Guardamos sus datos mientras su cuenta esté activa. Si elimina su cuenta desde Ajustes, eliminamos de forma permanente su perfil, las rondas que organizó (y sus chats), los grupos que creó (y sus chats), su membresía en grupos y sus mensajes en chats de grupo, su lista de amigos, sus calificaciones, su suscripción a notificaciones y sus bloqueos y, si había iniciado sesión, su cuenta de acceso. También se eliminan los reportes que usted hizo. Los registros de pago de eventos se conservan después de eliminar su cuenta, porque los necesitamos para la contabilidad; su nombre en ellos se reemplaza por “Usuario eliminado”, y cualquier evento próximo que haya pagado se le reembolsa completo.", "Una excepción: si otra persona hizo un reporte sobre usted, lo conservamos aunque elimine su cuenta, porque es parte de nuestro registro de seguridad y no algo que alguien deba poder borrar al irse."] },
  { h: "Sus opciones", list: ["La ubicación es totalmente opcional: la aplicación funciona sin ella, solo que sin ordenar por distancia ni buscar campos cercanos.", "Puede editar su perfil (nombre, campo habitual, hándicap, bio) en cualquier momento desde Ajustes.", "Puede activar o desactivar las notificaciones desde Ajustes.", "Puede bloquear o reportar a otra persona en cualquier momento desde su perfil.", "Puede eliminar su cuenta por completo desde Ajustes; vea arriba qué se elimina."] },
  { h: "Privacidad de menores", p: ["Foursome no está dirigido a menores de 18 años, y no recopilamos a sabiendas información de personas menores de esa edad."] },
  { h: "Seguridad", p: ["Tomamos medidas razonables para proteger su información, pero ninguna aplicación o servicio puede garantizar seguridad total. Use una contraseña segura y única si crea una cuenta completa."] },
  { h: "Cambios a esta política", p: ["Podemos actualizar esta política conforme Foursome cambie. Si hacemos un cambio importante, haremos lo posible por avisarle en la aplicación."] },
  { h: "Contacto", p: ["¿Preguntas sobre sus datos o esta política? Escríbanos a foursomeapp.golf@gmail.com."] },
];

const REFUND_SECTIONS = [
  { h: "En resumen", p: ["Usar Foursome es gratis. Lo único que se puede pagar es un espacio en un evento Foursome, y esos espacios tienen reembolso completo si usted cancela a tiempo o si nosotros cancelamos el evento."] },
  { h: "Cancelar su espacio", p: ["Abra el evento en la pestaña Eventos y toque \"Cancelá con reembolso completo\". Puede hacerlo hasta el plazo de cancelación indicado en el evento (por ejemplo, 48 horas antes de que empiece). Se le devuelve todo lo que pagó; nosotros cubrimos las comisiones del procesamiento del pago."] },
  { h: "Después del plazo", p: ["Una vez pasado el plazo, los pagos no son reembolsables, porque normalmente no se puede llenar un espacio con tan poco tiempo."] },
  { h: "Si cancelamos un evento", p: ["Si Foursome cancela un evento, a todas las personas que pagaron se les reembolsa el monto completo: los pagos con tarjeta automáticamente, y los pagos por SINPE Móvil a mano en un plazo de 3 días hábiles (ver abajo)."] },
  { h: "Cómo le llega el reembolso", p: ["Los pagos con tarjeta se reembolsan automáticamente a la misma tarjeta, por medio de ONVO Pay. El tiempo en que aparecen depende de su banco, normalmente unos días hábiles. Si un reembolso falla, lo reintentaremos o nos pondremos en contacto con usted.", "Los pagos por SINPE Móvil no se pueden reembolsar automáticamente, así que los enviamos a mano: cuando usted cancela (o nosotros cancelamos el evento), su espacio se libera de inmediato, la app le pide confirmar el número de SINPE Móvil al que enviamos el dinero, y le enviamos el monto completo a ese número en un plazo de 3 días hábiles. La app muestra \"Reembolso por enviar por SINPE Móvil\" hasta que se envía, y \"Reembolsado\" después, con una notificación."] },
  { h: "Pagar por un grupo", p: ["Puede pagar hasta 4 espacios a la vez y poner el nombre de sus invitados. Antes del plazo, puede reembolsar el espacio de un invitado (su parte: el total dividido en partes iguales) o cancelar el resto. Si usó un código de descuento, los reembolsos son de lo que realmente pagó."] },
  { h: "Pagos sin terminar", p: ["Si empieza a pagar y no termina, no se le cobra nada, y su espacio reservado se libera después de 20 minutos. También puede liberarlo usted desde el evento."] },
  { h: "Contacto", p: ["¿Preguntas sobre un pago o un reembolso? Escríbanos a foursomeapp.golf@gmail.com."] },
];

module.exports = { LEGAL_EFFECTIVE_DATE, TERMS_EFFECTIVE_DATE, TERMS_SECTIONS, PRIVACY_SECTIONS, REFUND_SECTIONS };
